 * no cap is set and the banded level stands. Soft-deleted owners no longer occupy their
 * household, so they are not counted as members.
 */
public class CapMembershipLevel {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            return;
        }
        Integer maxLevel = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getId() == null) {
                continue;
            }
            if (Boolean.TRUE.equals(existing.getDeleted())) {
                continue;
            }
            if (!householdId.equals(Households.householdId(existing.getLastName(), existing.getPostcode()))) {
                continue;
            }
            Integer level = existing.getMembershipLevel();
            if (level != null && (maxLevel == null || level > maxLevel)) {
                maxLevel = level;
            }
        }
        if (maxLevel != null) {
            owner.setMembershipLevelCap(maxLevel + 1);
        }
    }
}

